const server=createServer(async(req,res)=>{if(req.url==='/qa-blank'){res.setHeader('Content-Type','text/html');res.end('<!doctype html><script src="/web/dist/venue_layout_kernel.js"></script>');return;}try{const u=new URL(req.url,'http://localhost').pathname;let p=u.startsWith('/fixtures/')?join(fixtures,u.slice(10)):npmRoot&&u.startsWith('/web/')?join(npmRoot,u.slice(5)):join(root,u);if(p.endsWith('/'))p+='index.html';res.setHeader('Content-Type',({'.js':'text/javascript','.html':'text/html','.json':'application/json','.png':'image/png'}[extname(p)]||'application/octet-stream'));res.end(await readFile(p));}catch{res.statusCode=404;res.end();}});await new Promise(r=>server.listen(0,'127.0.0.1',r));const base=`http://127.0.0.1:${server.address().port}`;
