await p.evaluate(async({document:doc,resources,presentation,width,zoom,height})=>{const{mount}=await import('/web/src/index.js');document.body.replaceChildren();document.body.style.cssText='margin:0;background:white';const host=document.createElement('div');host.style.cssText=`width:${width}px;height:${height}px`;document.body.append(host);const v=mount(host,{document:doc,resources,seatPresentation:presentation});v.svg.style.cssText=`width:${width}px;height:${height}px;display:block;min-height:0;background:white`;v.camera={x:0,y:0,width:width/zoom,height:height/zoom};v.update({});v.resizeObserver?.disconnect();v.svg.setAttribute('viewBox',`0 0 ${width/zoom} ${height/zoom}`);v.svg.setAttribute('preserveAspectRatio','none');},{document:motion.document,resources:fixture.resources,presentation:f.presentation||{},width,zoom,height:viewportHeight});
