await writeFile(join(out,'index.html'),`<!doctype html><meta charset="utf-8"><title>Blueprint raster evidence</title><h1>Actual Flutter / browser raster evidence</h1><p>${result.approval}</p>${gallery}<pre>${JSON.stringify(result,null,2).replaceAll('&','&amp;').replaceAll('<','&lt;')}</pre>`);console.log(`Raster: ${results.length} comparisons, ${failures.length} failures; ${out}/result.json`);if(!result.reviewedRasterPass)process.exitCode=1;
